cards.solution:
const tombol = document.querySelector("#tambah");
function ambil() {
  const stok = Number(tombol.dataset.stok) - 1;
  tombol.dataset.stok = stok;
  if (stok === 0) {
    tombol.disabled = true;
    tombol.textContent = "Stok habis";
  }
}
ambil();
console.log(tombol.dataset.stok, tombol.disabled);
ambil();
console.log(tombol.dataset.stok, tombol.disabled);
console.log(tombol.textContent);
